const r = $input.first().json.report || {};
const t = r.totals || {};
const bySev = Array.isArray(r.by_severity) ? r.by_severity : [];
const byCat = Array.isArray(r.by_category) ? r.by_category : [];
const recent = Array.isArray(r.recent_open) ? r.recent_open : [];

function esc(s) { return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function dateShort(s) { if (!s) return '-'; return new Date(s).toISOString().substring(0,10); }
const sevColor = { low:'#888', medium:'#3b82f6', high:'#e67e22', urgent:'#c00' };

const rowsRecent = recent.map(i => {
  const slaBreach = i.days_assigned != null && i.days_assigned > i.sla_days;
  const cls = slaBreach ? ' style="background:#fee"' : (i.severity === 'urgent' ? ' style="background:#fff8e0"' : '');
  return `<tr${cls}>
    <td><span style="background:${sevColor[i.severity] || '#888'};color:white;padding:2px 8px;border-radius:10px;font-size:11px;font-weight:bold">${esc(i.severity)}</span></td>
    <td>${esc(i.project_name)}</td>
    <td>${esc(i.category || '-')} / ${esc(i.responsible_trade || '-')}</td>
    <td>${esc(i.status)}</td>
    <td>${esc(i.assigned_to || '-')}</td>
    <td style="text-align:right">${i.days_open}d</td>
    <td style="text-align:right;${slaBreach ? 'color:#c00;font-weight:600' : ''}">${i.days_assigned != null ? i.days_assigned + 'd / ' + i.sla_days + 'd SLA' : '-'}</td>
    <td style="font-size:12px;color:#555">${esc(i.desc_preview)}...</td>
  </tr>`;
}).join('');

const rowsSev = bySev.map(s => `<tr><td><span style="background:${sevColor[s.severity] || '#888'};color:white;padding:2px 8px;border-radius:10px;font-size:11px">${esc(s.severity)}</span></td><td style="text-align:right;font-weight:600">${s.open_count}</td></tr>`).join('');
const rowsCat = byCat.map(c => `<tr><td>${esc(c.category)}</td><td style="text-align:right">${c.open_count}</td></tr>`).join('');

const html = `<!DOCTYPE html><html lang="es"><head><meta charset="utf-8"><title>Aftercare Overview - ArquitAI</title>
<style>
  body{font-family:system-ui,sans-serif;max-width:1200px;margin:32px auto;padding:0 20px;color:#222;background:#f7f7f8}
  h1{margin:0 0 8px}
  .sub{color:#888;font-size:13px;margin-bottom:24px}
  h2{margin:32px 0 12px;font-size:18px;border-bottom:1px solid #ddd;padding-bottom:6px}
  .cards{display:grid;grid-template-columns:repeat(6,1fr);gap:10px;margin-bottom:24px}
  .card{background:#fff;border:1px solid #ddd;border-radius:8px;padding:12px;text-align:center}
  .card h3{margin:0 0 4px;font-size:11px;color:#666;text-transform:uppercase}
  .card .v{font-size:22px;font-weight:600}
  table{width:100%;border-collapse:collapse;background:#fff;border:1px solid #ddd;border-radius:8px;overflow:hidden;font-size:13px}
  th,td{padding:8px 10px;border-bottom:1px solid #eee;text-align:left}
  th{background:#f0f0f3;font-weight:600;font-size:11px;text-transform:uppercase;color:#555}
  tr:last-child td{border-bottom:none}
  .row-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}
  .meta{font-size:12px;color:#888;margin-top:24px}
  @media (max-width:900px){.cards{grid-template-columns:repeat(3,1fr)} .row-grid{grid-template-columns:1fr}}
</style></head><body>
<h1>Aftercare Overview - ArquitAI</h1>
<p class="sub">Vista agregada de incidencias postventa LOE. Para SLA breach dedicado: cron_aftercare_sla_breach diario 08:30.</p>
<div class="cards">
  <div class="card"><h3>Total</h3><div class="v">${t.total || 0}</div></div>
  <div class="card"><h3>Open</h3><div class="v" style="color:${t.open > 0 ? '#e67e22' : '#27ae60'}">${t.open || 0}</div></div>
  <div class="card"><h3>High/Urgent</h3><div class="v" style="color:${t.urgent_high > 0 ? '#c00' : '#27ae60'}">${t.urgent_high || 0}</div></div>
  <div class="card"><h3>In progress</h3><div class="v">${t.in_progress || 0}</div></div>
  <div class="card"><h3>SLA breach</h3><div class="v" style="color:${t.sla_breach > 0 ? '#c00' : '#27ae60'}">${t.sla_breach || 0}</div></div>
  <div class="card"><h3>Resolved 30d</h3><div class="v" style="color:#27ae60">${t.resolved_30d || 0}</div></div>
</div>
<div class="row-grid">
  <div>
    <h2>Open por severidad</h2>
    <table><thead><tr><th>severidad</th><th style="text-align:right">open</th></tr></thead><tbody>${rowsSev || '<tr><td colspan="2" style="text-align:center;color:#888;padding:14px">Sin incidencias open</td></tr>'}</tbody></table>
  </div>
  <div>
    <h2>Open por categoria</h2>
    <table><thead><tr><th>categoria</th><th style="text-align:right">open</th></tr></thead><tbody>${rowsCat || '<tr><td colspan="2" style="text-align:center;color:#888;padding:14px">Sin incidencias open</td></tr>'}</tbody></table>
  </div>
</div>
<h2>Incidentes open recientes (top 25 por severidad)</h2>
<table>
  <thead><tr><th>sev</th><th>proyecto</th><th>cat / gremio</th><th>status</th><th>asignado</th><th style="text-align:right">dias</th><th style="text-align:right">desde asign</th><th>desc</th></tr></thead>
  <tbody>${rowsRecent || '<tr><td colspan="8" style="text-align:center;color:#888;padding:18px">Sin incidencias open (estado saludable)</td></tr>'}</tbody>
</table>
<div class="meta">Generado ${new Date().toISOString()}</div>
</body></html>`;

return [{ json: { html } }];
